"""Literal Save download-option markup plus zero-size inline baseline markers."""
from pathlib import Path
import json
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download'
labels={'ko':{'json':('다시 열기용 JSON','검사 범위·상태·안전한 결과'),'csv':('CSV','분류별 판정과 안전한 차이 목록'),'html':('HTML','브라우저에서 읽는 예시 보고서')},'en':{'json':('JSON for reopening','Scope, states and safe findings'),'csv':('CSV','Category outcomes and safe findings'),'html':('HTML','Readable sample report')}}
cases=[dict(id=f'{lang}-{width}-{format}-{int(selected)}',lang=lang,width=width,format=format,title=title,description=desc,selected=selected)for lang,formats in labels.items()for width in [209.328125,317.328125,344]for format,(title,desc)in formats.items()for selected in [False,True]]
(o/'downloadoption-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes())
script='const cases='+json.dumps(cases,ensure_ascii=False)+""";for(const c of cases){const f=document.createElement('div');f.className='fixture';f.dataset.id=c.id;f.style.width=c.width+'px';f.innerHTML=`<label class="download-option"><input type="checkbox" data-format="${c.format}" ${c.selected?'checked':''}><span><strong><i class="baseline title-baseline"></i>${c.title}</strong><i class="baseline description-baseline"></i><small>${c.description}</small></span></label>`;f.querySelector('input').name=c.id;document.getElementById('fixtures').append(f)}
function read(){return [...document.querySelectorAll('.fixture')].map(f=>{const e=f.firstChild,r=e.getBoundingClientRect(),b=x=>{const q=x.getBoundingClientRect();return{x:q.x-r.x,y:q.y-r.y,width:q.width,height:q.height}},s=getComputedStyle(e),input=e.querySelector('input'),title=e.querySelector('strong'),desc=e.querySelector('small'),range=document.createRange();range.selectNodeContents(desc);return{id:f.dataset.id,width:r.width,height:r.height,checkbox:b(input),body:b(e.querySelector('span')),title:b(title),titleText:title.textContent,descriptionText:desc.textContent,descriptionBaseline:b(e.querySelector('.description-baseline')).y,descriptionLines:[...range.getClientRects()].map(x=>({x:x.x-r.x,width:x.width})),selected:input.checked,bg:s.backgroundColor,border:s.borderColor,shadow:s.boxShadow,titleColor:getComputedStyle(title).color,descriptionColor:getComputedStyle(desc).color}})}
const first=document.querySelector('.fixture');let changes=0;first.addEventListener('change',()=>{changes++});const log=document.getElementById('live');function live(){const c=first.querySelector('input');log.textContent=JSON.stringify({selected:c.checked,changes,focused:document.activeElement===c,focusVisible:c.matches(':focus-visible'),bg:getComputedStyle(first.firstChild).backgroundColor})}for(const kind of ['change','focusin','focusout','keydown','keyup','pointerup'])first.addEventListener(kind,()=>setTimeout(live,0));live();
document.getElementById('downloadoption-record').onclick=async()=>{await document.fonts.ready;const res=await fetch('/evidence/source-sidebar.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows:read()})});if(!res.ok)throw Error('Evidence failed');document.getElementById('downloadoption-record').textContent='DownloadOption recorded'};"""
(o/'downloadoption.html').write_text('<!doctype html><meta charset="utf-8"><title>DownloadOption · original isolation</title><link rel="stylesheet" href="downloadoption-original.css"><style>body{min-width:1100px}.fixture{position:absolute;left:30px;top:100px}.fixture:not(:first-child){visibility:hidden;pointer-events:none}.baseline{display:inline-block;width:0;height:0;padding:0;margin:0;border:0;vertical-align:baseline}#downloadoption-record{position:fixed;left:30px;top:20px}#live{position:absolute;left:500px;top:100px;white-space:pre-wrap}</style><button id="downloadoption-record">Record DownloadOption</button><div id="fixtures"></div><pre id="live"></pre><script>'+script+'</script>')
for p in [o/'downloadoption-cases.json',r/'docs/replica/source/downloadoption-cases.json']:p.write_text(json.dumps(cases,ensure_ascii=False,indent=2)+'\n')
print(len(cases),'literal DownloadOption cases')
